    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;

    for (int64_t i = idx * 4; i < numel; i += stride * 4) {
        if (i + 3 < numel) {
            float4 x_vec = *reinterpret_cast<const float4*>(x + i);
            float4 y_vec = *reinterpret_cast<const float4*>(y + i);
            float4 result;
            result.x = (x_vec.x + y_vec.x) * y_vec.x;
            result.y = (x_vec.y + y_vec.y) * y_vec.y;
            result.z = (x_vec.z + y_vec.z) * y_vec.z;
            result.w = (x_vec.w + y_vec.w) * y_vec.w;
            *reinterpret_cast<float4*>(out + i) = result;
        } else {
            for (int64_t j = i; j < numel && j < i + 4; ++j) {
