// cuBLASLt linear: output = input @ weight.T + bias
// input: [M, K], weight: [N, K], bias: [N], output: [M, N]
torch::Tensor linear_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(), "All tensors must be CUDA");
    TORCH_CHECK(input.is_contiguous() && weight.is_contiguous() && bias.is_contiguous(), "All tensors must be contiguous");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");

    int64_t M = input.size(0);
    int64_t K = input.size(1);
    int64_t N = weight.size(0);

    auto output = torch::empty({M, N}, input.options());

    cublasLtHandle_t ltHandle;
    cublasLtCreate(&ltHandle);

    cublasLtMatmulDesc_t operationDesc;
    cublasLtMatrixLayout_t Adesc, Bdesc, Cdesc, Ddesc;
    cublasLtMatmulPreference_t preference;

    // We compute: output = input * weight^T + bias
    // cuBLASLt uses column-major, so we compute in transposed form:
    // output^T = weight * input^T  (both column-major)
    // A=weight [N,K] col-major = weight [K,N] row-major  -> transa=CUBLAS_OP_N
    // B=input  [K,M] col-major = input  [M,K] row-major  -> transb=CUBLAS_OP_T
    // C=output [N,M] col-major = output [M,N] row-major

    cublasOperation_t transa = CUBLAS_OP_T;  // transpose weight (row-major K,N -> col-major N,K)
    cublasOperation_t transb = CUBLAS_OP_N;

    // For row-major inputs treated as col-major transposed:
    // A = weight [N x K] row-major => treat as [K x N] col-major, transa=CUBLAS_OP_T
    // B = input  [M x K] row-major => treat as [K x M] col-major, transb=CUBLAS_OP_N
    // Result: [N x M] col-major = output [M x N] row-major

    cublasLtMatmulDescCreate(&operationDesc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa));
    cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb));

    // Set epilogue to bias add
    cublasLtEpilogue_t epilogue = CUBLASLT_EPILOGUE_BIAS;
    cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epilogue, sizeof(epilogue));
    const void* biasPtr = bias.data_ptr<float>();
    cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &biasPtr, sizeof(biasPtr));

    // A = weight [K x N] (treated as col-major K rows, N cols)
    cublasLtMatrixLayoutCreate(&Adesc, CUDA_R_32F, K, N, K);
    // B = input  [K x M] (treated as col-major K rows, M cols)
    cublasLtMatrixLayoutCreate(&Bdesc, CUDA_R_32F, K, M, K);
    // C = output [N x M]
    cublasLtMatrixLayoutCreate(&Cdesc, CUDA_R_32F, N, M, N);
    // D = output [N x M]
    cublasLtMatrixLayoutCreate(&Ddesc, CUDA_R_32F, N, M, N);

    cublasLtMatmulPreferenceCreate(&preference);
    size_t workspaceSize = 32 * 1024 * 1024;
    cublasLtMatmulPreferenceSetAttribute(preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                                          &workspaceSize, sizeof(workspaceSize));

    cublasLtMatmulHeuristicResult_t heuristicResult = {};
    int returnedResults = 0;
    cublasStatus_t heurStatus = cublasLtMatmulAlgoGetHeuristic(
        ltHandle, operationDesc, Adesc, Bdesc, Cdesc, Ddesc,
        preference, 1, &heuristicResult, &returnedResults);

    bool use_cublaslt = (heurStatus == CUBLAS_STATUS_SUCCESS && returnedResults > 0);

    if (use_cublaslt) {
        auto workspace = torch::empty({(int64_t)workspaceSize}, input.options().dtype(torch::kUInt8));
        float alpha = 1.0f, beta_val = 0.0f;
        cublasStatus_t status = cublasLtMatmul(
            ltHandle, operationDesc,
            &alpha,
            weight.data_ptr<float>(), Adesc,
            input.data_ptr<float>(),  Bdesc,
            &beta_val,
            output.data_ptr<float>(), Cdesc,
            output.data_ptr<float>(), Ddesc,
            &heuristicResult.algo,
            workspace.data_ptr(), workspaceSize,
            at::cuda::getCurrentCUDAStream()
        );
        if (status != CUBLAS_STATUS_SUCCESS) {
            // fallback
            output = at::addmm(bias, input, weight.t());
        }
    } else {
        output = at::addmm(bias, input, weight.t());
    }

    cublasLtMatmulPreferenceDestroy(preference);
    cublasLtMatrixLayoutDestroy(Adesc);
    cublasLtMatrixLayoutDestroy(Bdesc);
    cublasLtMatrixLayoutDestroy(Cdesc);
    cublasLtMatrixLayoutDestroy(Ddesc);
    cublasLtMatmulDescDestroy(operationDesc);
    cublasLtDestroy(ltHandle);

    return output;
}
